  const signIn=async()=>{if(!email.trim()||!password){setNotice("Enter your administrator email and password.");return;}setBusy(true);setNotice("");try{const {data,error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error;await verifyAdmin(data.user);}catch(e){setNotice(e.message||"Sign in failed.");}finally{setBusy(false);}};
  const signOut=async()=>{await supabase.auth.signOut();setSessionUser(null);setRole("");setPassword("");};
  const logAction=async(action,resource_type,resource_id,metadata={})=>{if(!sessionUser)return;const {data,error}=await supabase.from("platform_audit_log").insert({actor_id:sessionUser.id,action,resource_type,resource_id:String(resource_id||""),metadata}).select().maybeSingle();if(!error&&data)setAuditRows(cur=>[data,...cur].slice(0,100));};
  const savePage=async(publish)=>{setPageSaving(true);setNotice("");const next={page_key:publish?"homepage":"homepage-draft",title:draft.title||"Homepage",content:{...draft.content,sections:sectionOrder},custom_html:draft.custom_html||"",custom_css:draft.custom_css||"",custom_js:draft.custom_js||"",seo:draft.seo||{},is_published:publish,updated_by:sessionUser.id,revision:(page?.revision||0)+1,updated_at:new Date().toISOString()};try{const {data,error}=await supabase.from("platform_pages").upsert(next,{onConflict:"page_key"}).select().single();if(error)throw error;if(publish)await supabase.from("platform_pages").delete().eq("page_key","homepage-draft");setPage(data);setDraft(data);await logAction(publish?"homepage.publish":"homepage.draft","platform_pages",publish?"homepage":"homepage-draft",{revision:data.revision});setNotice(publish?"Homepage changes published. Visitors will receive the latest version.":"Draft saved privately. The current live homepage is unchanged.");}catch(e){setNotice(e.message||"Could not save homepage.");}finally{setPageSaving(false);}};
  const moveSection=(target)=>{if(!dragSection||dragSection===target)return;const next=[...sectionOrder];const from=next.indexOf(dragSection),to=next.indexOf(target);if(from<0||to<0)return;next.splice(from,1);next.splice(to,0,dragSection);setSectionOrder(next);setDragSection("");};
  const editPost=(p)=>{setPost(p);setBlogTitle(p.title);setBlogSlug(p.slug);setBlogExcerpt(p.excerpt||"");setBlogBody(p.body||"");setBlogCategory(p.category||"Company news");setBlogImage(p.cover_image_url||"");setBlogStatus(p.status||"draft");setTab("Blog");};
  const newPost=()=>{setPost(null);setBlogTitle("");setBlogSlug("");setBlogExcerpt("");setBlogBody("");setBlogCategory("Company news");setBlogImage("");setBlogStatus("draft");};
  const savePost=async()=>{if(!blogTitle.trim()||!blogSlug.trim()||!blogBody.trim()){setNotice("Blog title, URL slug and article body are required.");return;}setPostSaving(true);try{const row={title:blogTitle.trim(),slug:blogSlug.toLowerCase().trim().replace(/[^a-z0-9-]+/g,"-").replace(/^-|-$/g,""),excerpt:blogExcerpt,body:blogBody,category:blogCategory,cover_image_url:blogImage,status:blogStatus,author_name:"DuKu Editorial",created_by:sessionUser.id,published_at:blogStatus==="published"?(post?.published_at||new Date().toISOString()):null,updated_at:new Date().toISOString()};const q=post?supabase.from("blog_posts").update(row).eq("id",post.id):supabase.from("blog_posts").insert(row);const {data,error}=await q.select().single();if(error)throw error;setPosts(cur=>post?cur.map(x=>x.id===data.id?data:x):[data,...cur]);setPost(data);await logAction(post?"blog.update":"blog.create","blog_posts",data.id,{title:data.title,status:data.status});setNotice("Article saved.");}catch(e){setNotice(e.message||"Could not save article.");}finally{setPostSaving(false);}};
  const deletePost=async(p)=>{if(!window.confirm("Delete this blog post permanently?"))return;const {error}=await supabase.from("blog_posts").delete().eq("id",p.id);if(error)setNotice(error.message);else{setPosts(cur=>cur.filter(x=>x.id!==p.id));if(post?.id===p.id)newPost();await logAction("blog.delete","blog_posts",p.id,{title:p.title});setNotice("Article deleted.");}};
  const saveAdminAccess=async()=>{if(role!=="super_admin"||!selectedAdmin)return;if(!accessPermissions.length){setNotice("Select at least one section. Remove all access by changing the account role to User or Support.");return;}const {error}=await supabase.from("profiles").update({admin_permissions:accessPermissions}).eq("id",selectedAdmin.id);if(error)setNotice(error.message);else{setMembers(cur=>cur.map(m=>m.id===selectedAdmin.id?{...m,admin_permissions:accessPermissions}:m));await logAction("admin.permissions.update","profiles",selectedAdmin.id,{permissions:accessPermissions});setNotice("Administrator section access saved.");setSelectedAdmin(null);}};
   const changeMemberRole=async(member,newRole)=>{if(role!=="super_admin"&&["admin","super_admin"].includes(newRole)){setNotice("Only the super admin can appoint administrators or super administrators.");return;}if(role!=="super_admin"&&["admin","super_admin"].includes(member.platform_role)){setNotice("Only the super admin can change another administrator's role.");return;}if(member.id===sessionUser.id&&newRole!=="super_admin"){setNotice("You cannot remove your own administrator access from this screen.");return;}const nextPermissions=newRole==="admin"&&member.platform_role!=="admin"?["Overview"]:(member.admin_permissions||[]);const {error}=await supabase.from("profiles").update({platform_role:newRole,admin_permissions:nextPermissions}).eq("id",member.id);if(error)setNotice(error.message);else{setMembers(cur=>cur.map(x=>x.id===member.id?{...x,platform_role:newRole}:x));await logAction("member.role.update","profiles",member.id,{role:newRole});setNotice("Member role updated.");}};
