  const connectWorkspaceDomain=async()=>{if(!workspace||!domainSiteId){setNotice("Create a website first, then choose it here.");return;}let domain=domainInput.trim().toLowerCase();if(domain.startsWith("https://"))domain=domain.slice(8);else if(domain.startsWith("http://"))domain=domain.slice(7);if(domain.startsWith("www."))domain=domain.slice(4);if(domain.endsWith("/"))domain=domain.slice(0,-1);const labels=domain.split(".");if(domain.length>253||labels.length<2||!labels.every(label=>label.length>0&&label.length<=63&&/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label))){setNotice("Enter a valid domain, for example example.com.");return;}setDomainBusy(true);setNotice("");try{const token="duku-fca="+(window.crypto?.randomUUID?window.crypto.randomUUID().replace(/-/g,""):Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2));const {data,error}=await supabase.from("site_domains").insert({site_id:domainSiteId,domain,domain_type:"custom",verification_status:"pending",verification_token:token,dns_record_name:"_duku-verification."+domain}).select("*").single();if(error)throw error;setDomainRows(v=>[data,...v]);setDomainInput("");setNotice("Domain added. Add the TXT verification record shown below, then verify ownership.");}catch(e){setNotice(e.message||"Could not add this domain.");}finally{setDomainBusy(false);}};
