  const startDomainTransfer=async()=>{if(!transferQuote||!transferAuthCode.trim()){setNotice("Enter the authorisation code from your current registrar.");return;}const price=Number(transferQuote.quoted_price);if(!window.confirm("Submit the domain transfer to DuKu registrar?\n\nDomain: "+transferQuote.domain+"\nTransfer price: $"+price.toFixed(2)+" USD\nTerm: "+transferQuote.years+" year(s)\nAuto-renew: "+(transferAutoRenew?"On":"Off")+"\n\nThe registrar may charge the payment method on file. The transfer can take several days. Continue only if you approve this exact price and the registrant details."))return;setTransferBusy(true);setNotice("");try{const {data,error}=await supabase.functions.invoke("duku-domain-manager",{body:{action:"transfer_start",site_id:transferSiteId,domain:transferQuote.domain,request_id:transferQuote.id,expected_price:price,confirm:true,auto_renew:transferAutoRenew,auth_code:transferAuthCode,contact_information:transferContact}});if(error)throw error;if(data?.error)throw new Error(data.error);setTransferAuthCode("");setTransferQuote(null);setTransferDomain("");await refreshWorkspaceDomains();await refreshWorkspaceTransfers();setNotice(data?.message||"Transfer submitted to the registrar.");}catch(e){setNotice(e.message||"Could not submit the domain transfer.");}finally{setTransferBusy(false);}};
