  const importProject=async()=>{const token=window.location.pathname.match(/\/share\/([a-f0-9]+)/i)?.[1];if(!token)return;if(!user){setNotice("Sign in first, then open this share link again.");return;}try{const {data:importedSiteId,error}=await supabase.rpc("duku_import_shared_site",{p_token:token});if(error)throw error;if(!importedSiteId)throw new Error("Import did not return a project ID.");setNotice("Project imported successfully. Refreshing your workspace…");window.history.replaceState({},"","/u/"+user.id+"/workspace/"+(workspace?.slug||"home"));await load();}catch(e){setNotice(e.message||"Could not import this project.");}};
  useEffect(()=>{if(user&&window.location.pathname.startsWith("/share/"))importProject();},[user]); // eslint-disable-line react-hooks/exhaustive-deps
  const filtered=templates.filter(t=>(templateFilter==="All"||t.category===templateFilter)&&(!workspaceSearch||t.name.toLowerCase().includes(workspaceSearch.toLowerCase())||t.description.toLowerCase().includes(workspaceSearch.toLowerCase())));
